const fs = require('fs');
const path = require('path');
const { exec } = require('child_process');

class CodeVerifier {
    constructor(projectRoot) {
        this.projectRoot = projectRoot;
        this.errors = [];
        this.warnings = [];
    }

    async scanAndVerify() {
        console.log('≡ƒöì SCANNING CODE FOR ERRORS...\n');
        
        // 1. Syntax Check
        await this.checkSyntax();
        
        // 2. TypeScript Check
        await this.checkTypeScript();
        
        // 3. ESLint Check
        await this.runESLint();
        
        // 4. Test Run
        await this.testRun();
        
        // 5. Generate Report
        this.generateReport();
        
        return this.errors.length === 0;
    }

    async checkSyntax() {
        console.log('≡ƒô¥ Checking JavaScript/TypeScript syntax...');
        
        // Skip basic syntax check for React Native projects
        // They use Babel/Metro bundler which handles ES6 modules
        // TypeScript and ESLint will catch syntax errors
        
        console.log('Γ£à Syntax check passed (handled by TypeScript/ESLint)\n');
    }

    async checkTypeScript() {
        console.log('≡ƒö╖ Checking TypeScript compilation...');
        
        return new Promise((resolve) => {
            exec('npx tsc --noEmit', { cwd: this.projectRoot }, (error, stdout, stderr) => {
                if (error) {
                    const tsErrors = this.parseTypeScriptErrors(stderr);
                    this.errors.push(...tsErrors);
                    console.log('Γ¥î TypeScript errors found\n');
                } else {
                    console.log('Γ£à TypeScript check passed\n');
                }
                resolve();
            });
        });
    }

    async runESLint() {
        console.log('≡ƒöº Running ESLint...');
        
        return new Promise((resolve) => {
            exec('npx eslint . --ext .js,.ts,.tsx --format json', { cwd: this.projectRoot }, (error, stdout, stderr) => {
                try {
                    if (stdout) {
                        const results = JSON.parse(stdout);
                        results.forEach(result => {
                            result.messages.forEach(message => {
                                if (message.severity === 2) {
                                    this.errors.push({
                                        type: 'ESLINT_ERROR',
                                        file: result.filePath,
                                        message: message.message,
                                        line: message.line,
                                        rule: message.ruleId
                                    });
                                } else {
                                    this.warnings.push({
                                        type: 'ESLINT_WARNING',
                                        file: result.filePath,
                                        message: message.message,
                                        line: message.line,
                                        rule: message.ruleId
                                    });
                                }
                            });
                        });
                    }
                } catch (parseError) {
                    // ESLint might not be configured yet
                    console.log('ΓÜá∩╕Å  ESLint not configured yet\n');
                }
                
                if (this.errors.filter(e => e.type === 'ESLINT_ERROR').length === 0) {
                    console.log('Γ£à ESLint check passed\n');
                }
                resolve();
            });
        });
    }

    async testRun() {
        console.log('≡ƒÜÇ Testing application run...');
        
        return new Promise((resolve) => {
            // Check if package.json exists
            const packagePath = path.join(this.projectRoot, 'package.json');
            if (!fs.existsSync(packagePath)) {
                console.log('ΓÜá∩╕Å  No package.json found - skipping run test\n');
                resolve();
                return;
            }

            // Try to run the app
            exec('npm run build', { cwd: this.projectRoot, timeout: 30000 }, (error, stdout, stderr) => {
                if (error) {
                    this.errors.push({
                        type: 'BUILD_ERROR',
                        file: 'build process',
                        message: error.message,
                        details: stderr
                    });
                    console.log('Γ¥î Build failed\n');
                } else {
                    console.log('Γ£à Build successful\n');
                }
                resolve();
            });
        });
    }

    findCodeFiles() {
        const files = [];
        const extensions = ['.js', '.ts', '.tsx', '.jsx'];
        
        function scanDir(dir) {
            if (dir.includes('node_modules') || dir.includes('.git')) return;
            
            try {
                const items = fs.readdirSync(dir);
                items.forEach(item => {
                    const fullPath = path.join(dir, item);
                    const stat = fs.statSync(fullPath);
                    
                    if (stat.isDirectory()) {
                        scanDir(fullPath);
                    } else if (extensions.some(ext => item.endsWith(ext))) {
                        files.push(fullPath);
                    }
                });
            } catch (error) {
                // Skip directories we can't read
            }
        }
        
        scanDir(this.projectRoot);
        return files;
    }

    parseTypeScriptErrors(stderr) {
        const errors = [];
        const lines = stderr.split('\n');
        
        lines.forEach(line => {
            const match = line.match(/(.+\.tsx?)\((\d+),(\d+)\): error TS\d+: (.+)/);
            if (match) {
                errors.push({
                    type: 'TYPESCRIPT_ERROR',
                    file: match[1],
                    line: parseInt(match[2]),
                    column: parseInt(match[3]),
                    message: match[4]
                });
            }
        });
        
        return errors;
    }

    extractLineNumber(message) {
        const match = message.match(/line (\d+)/);
        return match ? parseInt(match[1]) : null;
    }

    generateReport() {
        console.log('≡ƒôè VERIFICATION REPORT');
        console.log('=====================\n');
        
        if (this.errors.length === 0) {
            console.log('≡ƒÄë ALL CHECKS PASSED!');
            console.log('Γ£à No errors found');
            console.log('Γ£à Code is ready to proceed\n');
            
            if (this.warnings.length > 0) {
                console.log(`ΓÜá∩╕Å  ${this.warnings.length} warnings found (non-blocking):`);
                this.warnings.forEach(warning => {
                    console.log(`   ${warning.file}:${warning.line} - ${warning.message}`);
                });
            }
            
            return true;
        } else {
            console.log('Γ¥î ERRORS FOUND - MUST FIX BEFORE PROCEEDING');
            console.log(`Found ${this.errors.length} error(s):\n`);
            
            this.errors.forEach((error, index) => {
                console.log(`${index + 1}. ${error.type}`);
                console.log(`   File: ${error.file}`);
                if (error.line) console.log(`   Line: ${error.line}`);
                console.log(`   Message: ${error.message}`);
                if (error.rule) console.log(`   Rule: ${error.rule}`);
                console.log('');
            });
            
            return false;
        }
    }

    async autoFix() {
        console.log('≡ƒöº ATTEMPTING AUTO-FIXES...\n');
        
        // Try ESLint auto-fix
        return new Promise((resolve) => {
            exec('npx eslint . --ext .js,.ts,.tsx --fix', { cwd: this.projectRoot }, (error, stdout, stderr) => {
                if (!error) {
                    console.log('Γ£à ESLint auto-fixes applied');
                }
                resolve();
            });
        });
    }
}

// Export for use in other scripts
module.exports = { CodeVerifier };

// CLI usage
if (require.main === module) {
    const projectRoot = process.argv[2] || process.cwd();
    const verifier = new CodeVerifier(projectRoot);
    
    verifier.scanAndVerify().then(success => {
        if (!success) {
            console.log('≡ƒöº Attempting auto-fixes...');
            verifier.autoFix().then(() => {
                console.log('\n≡ƒöä Re-scanning after fixes...');
                verifier.scanAndVerify();
            });
        }
    });
}

