            Allergy_1.AllergyModel.getAllUserTriggerIngredients(userId)
        ]);
        // Check dietary restrictions
        for (const restriction of dietaryRestrictions) {
            const conflicting = recipeIngredients.filter(ingredient => excludedIngredients.some(excluded => ingredient.toLowerCase().includes(excluded.toLowerCase())));
            if (conflicting.length > 0) {
                conflicts.push({
                    type: 'dietary',
                    restriction: restriction.name,
                    conflictingIngredients: conflicting
                });
            }
        }
        // Check allergies (prioritize by severity)
        const allTriggers = [...triggerIngredients.severe, ...triggerIngredients.moderate, ...triggerIngredients.mild];
        const conflictingAllergies = recipeIngredients.filter(ingredient => allTriggers.some(trigger => ingredient.toLowerCase().includes(trigger.toLowerCase())));
        if (conflictingAllergies.length > 0) {
            conflicts.push({
                type: 'allergy',
                restriction: 'Food Allergies',
                conflictingIngredients: conflictingAllergies
            });
        }
        return {
            recipeId: '', // Will be set by caller
            isCompatible: conflicts.length === 0,
            conflicts
        };
    }
    static async filterRecipes(userId, recipes) {
        const results = [];
        for (const recipe of recipes) {
            const analysis = await this.analyzeRecipe(userId, recipe.ingredients);
            results.push({
                ...analysis,
                recipeId: recipe.id
            });
        }
        return results;
    }
}
