      ...(mealType && { mealType: mealType as string }),
      ...(cookingTime && { cookingTime: parseInt(cookingTime as string) }),
      ...(difficulty && { difficulty: difficulty as string }),
      ...(servings && { servings: parseInt(servings as string) })
    };

