  try {
    const { userId } = req.params;
    
    await ShoppingListModel.clearCompleted(userId);
    res.json({ success: true, message: 'Completed items cleared' });
  } catch (error) {
    res.status(500).json({ error: 'Failed to clear completed items' });
  }
});

