export interface DiscordEmbed {
  title: string;
  description?: string;
  color?: number;
  fields?: Array<{
    name: string;
    value: string;
    inline?: boolean;
  }>;
  thumbnail?: {
    url: string;
  };
  timestamp?: string;
}

export interface DiscordWebhookPayload {
  content?: string;
  embeds?: DiscordEmbed[];
  username?: string;
  avatar_url?: string;
}

export class DiscordWebhookService {
  private static webhookUrls = {
    newUser: process.env.DISCORD_WEBHOOK_NEW_USER || '',
    newRecipe: process.env.DISCORD_WEBHOOK_NEW_RECIPE || '',
    feedback: process.env.DISCORD_WEBHOOK_FEEDBACK || '',
    errors: process.env.DISCORD_WEBHOOK_ERRORS || ''
  };

  static async sendNewUserNotification(username: string, email: string, referralCode?: string): Promise<void> {
    const embed: DiscordEmbed = {
      title: '≡ƒÄë New User Joined!',
      color: 0x4CAF50,
      fields: [
        { name: 'Username', value: username, inline: true },
        { name: 'Email', value: email, inline: true }
      ],
      timestamp: new Date().toISOString()
    };

    if (referralCode) {
      embed.fields?.push({ name: 'Referral Code', value: referralCode, inline: true });
    }

    await this.sendWebhook('newUser', {
      embeds: [embed],
      username: 'Cook Smart Bot',
      avatar_url: 'https://example.com/bot-avatar.png'
    });
  }

  static async sendNewRecipeNotification(recipeTitle: string, username: string, cuisine: string, difficulty: string): Promise<void> {
    const embed: DiscordEmbed = {
      title: '≡ƒì│ New Recipe Added!',
      description: `**${recipeTitle}** by ${username}`,
      color: 0xFF9800,
      fields: [
        { name: 'Cuisine', value: cuisine, inline: true },
        { name: 'Difficulty', value: difficulty, inline: true }
      ],
      timestamp: new Date().toISOString()
    };

    await this.sendWebhook('newRecipe', {
      embeds: [embed],
      username: 'Cook Smart Bot'
    });
  }

  static async sendFeedbackNotification(username: string, feedback: string, rating?: number): Promise<void> {
    const embed: DiscordEmbed = {
      title: '≡ƒÆ¼ New Feedback',
      description: feedback,
      color: 0x2196F3,
      fields: [
        { name: 'User', value: username, inline: true }
      ],
      timestamp: new Date().toISOString()
    };

    if (rating) {
      embed.fields?.push({ name: 'Rating', value: `${rating}/5 Γ¡É`, inline: true });
    }

    await this.sendWebhook('feedback', {
      embeds: [embed],
      username: 'Cook Smart Bot'
    });
  }

  static async sendErrorNotification(error: string, context?: string): Promise<void> {
    const embed: any = {
      title: '≡ƒÜ¿ Application Error',
      description: error,
      color: 0xF44336,
      ...(context && { fields: [{ name: 'Context', value: context }] }),
      timestamp: new Date().toISOString()
    };

    await this.sendWebhook('errors', {
      embeds: [embed],
      username: 'Cook Smart Error Bot'
    });
  }

  private static async sendWebhook(type: keyof typeof this.webhookUrls, payload: DiscordWebhookPayload): Promise<void> {
    const webhookUrl = this.webhookUrls[type];
    
    if (!webhookUrl) {
      console.warn(`Discord webhook URL not configured for type: ${type}`);
      return;
    }

    try {
      await axios.post(webhookUrl, payload, {
        headers: {
          'Content-Type': 'application/json'
        },
        timeout: 5000
      });
    } catch (error) {
      console.error(`Failed to send Discord webhook (${type}):`, error);
    }
  }

  static async testWebhook(type: keyof typeof this.webhookUrls): Promise<boolean> {
    try {
      await this.sendWebhook(type, {
        content: '≡ƒº¬ Test message from Cook Smart',
        username: 'Cook Smart Test Bot'
      });
      return true;
    } catch (error) {
      return false;
    }
  }
}

import { DietaryRestrictionModel } from '../models/DietaryRestriction';
import { AllergyModel } from '../models/Allergy';

export interface RecipeConflict {
  type: 'dietary' | 'allergy';
  restriction: string;
  conflictingIngredients: string[];
}

export interface FilteredRecipe {
  recipeId: string;
  isCompatible: boolean;
  conflicts: RecipeConflict[];
}

export class RecipeFilterService {
  static async analyzeRecipe(userId: string, recipeIngredients: string[]): Promise<FilteredRecipe> {
    const conflicts: RecipeConflict[] = [];
    
    // Get user's dietary restrictions and allergies
    const [dietaryRestrictions, allergies, excludedIngredients, triggerIngredients] = await Promise.all([
      DietaryRestrictionModel.getUserRestrictions(userId),
      AllergyModel.getUserAllergies(userId),
      DietaryRestrictionModel.getAllUserExcludedIngredients(userId),
      AllergyModel.getAllUserTriggerIngredients(userId)
    ]);

    // Check dietary restrictions
    for (const restriction of dietaryRestrictions) {
      const conflicting = recipeIngredients.filter(ingredient => 
        excludedIngredients.some(excluded => 
          ingredient.toLowerCase().includes(excluded.toLowerCase())
        )
      );
      
      if (conflicting.length > 0) {
        conflicts.push({
          type: 'dietary',
          restriction: restriction.name,
          conflictingIngredients: conflicting
        });
      }
    }

    // Check allergies (prioritize by severity)
    const allTriggers = [...triggerIngredients.severe, ...triggerIngredients.moderate, ...triggerIngredients.mild];
    const conflictingAllergies = recipeIngredients.filter(ingredient =>
      allTriggers.some(trigger =>
        ingredient.toLowerCase().includes(trigger.toLowerCase())
      )
    );

    if (conflictingAllergies.length > 0) {
      conflicts.push({
        type: 'allergy',
        restriction: 'Food Allergies',
        conflictingIngredients: conflictingAllergies
      });
    }

    return {
      recipeId: '', // Will be set by caller
      isCompatible: conflicts.length === 0,
      conflicts
    };
  }

  static async filterRecipes(userId: string, recipes: Array<{id: string, ingredients: string[]}>): Promise<FilteredRecipe[]> {
    const results: FilteredRecipe[] = [];
    
    for (const recipe of recipes) {
      const analysis = await this.analyzeRecipe(userId, recipe.ingredients);
      results.push({
        ...analysis,
        recipeId: recipe.id
      });
    }
    
    return results;
  }
}

